#!/usr/bin/env python3
"""Normalize messy event CSVs and emit TabSeparated rows for ClickHouse INSERT."""
from __future__ import annotations

import csv
import sys
from datetime import datetime, timezone
from pathlib import Path


def normalize_cells(row: list[str]) -> list[str]:
    while len(row) > 1 and row[-1].strip() == "":
        row.pop()
    return row


def parse_timestamp(raw: str) -> str:
    s = raw.strip()
    if not s:
        raise ValueError("empty timestamp")
    # DD/MM/YYYY
    parts = s.split("/")
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        d, m, y = int(parts[0]), int(parts[1]), int(parts[2])
        dt = datetime(y, m, d, 0, 0, 0, tzinfo=timezone.utc)
        return dt.strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
    if "T" in s:
        iso = s.replace("Z", "+00:00")
        dt = datetime.fromisoformat(iso)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        else:
            dt = dt.astimezone(timezone.utc)
        return dt.strftime("%Y-%m-%d %H:%M:%S.%f")[:-3]
    raise ValueError(f"unrecognized timestamp: {raw!r}")


def parse_value(raw: str | None) -> str | None:
    if raw is None:
        return None
    t = raw.strip()
    if t == "" or t.upper() == "N/A" or t.lower() == "null":
        return None
    float(t)  # validate
    return t


def iter_clean_rows(csv_dir: Path):
    files = sorted(csv_dir.glob("events_*.csv"))
    for path in files:
        with path.open(newline="", encoding="utf-8") as f:
            reader = csv.reader(f)
            for row in reader:
                row = normalize_cells([c.strip() for c in row])
                if not row or all(c == "" for c in row):
                    continue
                if row[0] == "event_id" and len(row) >= 2 and row[1] == "event_ts":
                    continue
                if len(row) < 5:
                    raise ValueError(f"{path}: short row {row!r}")
                event_id, event_ts, user_id, event_type, value_raw = row[:5]
                ts_out = parse_timestamp(event_ts)
                val = parse_value(value_raw)
                yield event_id, ts_out, user_id, event_type, val


def main() -> None:
    root = Path(sys.argv[1] if len(sys.argv) > 1 else "/data/csv")
    for eid, ts, uid, etype, val in iter_clean_rows(root):
        vcol = "\\N" if val is None else val
        line = "\t".join([eid, ts, uid, etype, vcol])
        sys.stdout.write(line + "\n")


if __name__ == "__main__":
    main()

